import{_t as e,it as t,n,rt as r}from"./chunks/framework.BJvQKzTo.js";var i=JSON.parse(`{"title":"Jetpack Navigation","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/android/jetpack/navigation.md","filePath":"frontend/android/jetpack/navigation.md"}`),a={name:`frontend/android/jetpack/navigation.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="jetpack-navigation" tabindex="-1">Jetpack Navigation <a class="header-anchor" href="#jetpack-navigation" aria-label="Permalink to “Jetpack Navigation”">​</a></h1><h2 id="什么是navigation-有哪些优点-怎么用" tabindex="-1">什么是Navigation，有哪些优点，怎么用？ <a class="header-anchor" href="#什么是navigation-有哪些优点-怎么用" aria-label="Permalink to “什么是Navigation，有哪些优点，怎么用？”">​</a></h2><p>Navigation 是 Jetpack 的官方路由组件，统一管理页面跳转、返回栈，把页面之间的跳转关系写到一张导航图里，不用自己手动写 Intent、FragmentTransaction、管理回退栈</p><h3 id="支持activoty、fragment、dialog三种组件的路由行为" tabindex="-1">支持Activoty、fragment、Dialog三种组件的路由行为 <a class="header-anchor" href="#支持activoty、fragment、dialog三种组件的路由行为" aria-label="Permalink to “支持Activoty、fragment、Dialog三种组件的路由行为”">​</a></h3><p>以前：</p><ul><li>Fragment：手动 <code>replace</code>、<code>addToBackStack</code>，代码散落在各处</li><li>Activity：<code>startActivity(intent)</code></li><li>Dialog：自己 <code>show()</code>，路由很难统一管理</li></ul><p>Navigation：<strong>都可以在导航图里声明成 destination（目的地），统一用 <code>navController.navigate()</code> 跳转，统一管理返回栈</strong>。</p><ul><li>Fragment：最常用，放在 NavHost 容器里切换</li><li>Activity：可以作为导航节点，自动 startActivity</li><li>Dialog：<code>dialog</code> 类型目标，navigate 的时候弹出 Dialog，返回自动关闭，自动进返回栈</li></ul><blockquote><p>好处：整个 APP 的路由规则在一张图里看得见，不用到处找跳转代码。</p></blockquote><h3 id="支持deeplink深度链接、端外唤醒能力" tabindex="-1">支持DeepLink深度链接、端外唤醒能力 <a class="header-anchor" href="#支持deeplink深度链接、端外唤醒能力" aria-label="Permalink to “支持DeepLink深度链接、端外唤醒能力”">​</a></h3><p>eepLink = 用一个 URI 链接直接打开 APP 里<strong>指定页面</strong>，而不是只能打开首页。 例子：<code>myapp://detail?id=100</code></p><ul><li>浏览器、别的 APP、推送点击这个链接 → 直接跳转到详情页</li><li>可以配置参数，自动传给目标页面，和普通导航参数打通</li><li>也支持 HTTP 网页链接（App Links）</li></ul><h3 id="viewmodel支持-将viewmodel的生命周期限定为导航图-方便目标页面之间共享数据" tabindex="-1">ViewModel支持，将viewmodel的生命周期限定为导航图，方便目标页面之间共享数据 <a class="header-anchor" href="#viewmodel支持-将viewmodel的生命周期限定为导航图-方便目标页面之间共享数据" aria-label="Permalink to “ViewModel支持，将viewmodel的生命周期限定为导航图，方便目标页面之间共享数据”">​</a></h3><p>点：**<code>navGraphViewModels()</code>**Android De...</p><ul><li>普通 <code>viewModels()</code>：生命周期绑定单个 Fragment，页面销毁 ViewModel 就清</li><li><code>activityViewModels()</code>：绑定整个 Activity，只要 Activity 不杀就一直存在，容易残留脏数据</li><li>✅ <strong>导航图作用域 ViewModel</strong>：ViewModel 的生命周期 = 这个导航图还在返回栈里。</li></ul><blockquote><p>典型场景：结账流程（订单确认→填地址→支付），这 3 个 Fragment 放在同一个嵌套导航图。 三个页面共用一份订单 ViewModel；<strong>当你退出整个结账流程、导航图弹出回退栈时，ViewModel 自动销毁</strong>，不会残留到下一次下单。</p></blockquote><p>一句话：<strong>局部流程共享数据，流程结束自动释放，比 Activity 范围更安全</strong>。</p><h3 id="safe-args目标之间传递数据提供类型安全的gradle插件" tabindex="-1">Safe Args目标之间传递数据提供类型安全的Gradle插件 <a class="header-anchor" href="#safe-args目标之间传递数据提供类型安全的gradle插件" aria-label="Permalink to “Safe Args目标之间传递数据提供类型安全的Gradle插件”">​</a></h3><p>生 Bundle 传参的痛点：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// 字符串key，容易手敲错；类型写错运行时才崩</span></span>
<span class="line"><span>bundle.putLong(&quot;id&quot;, 100)</span></span>
<span class="line"><span>val id = bundle.getString(&quot;id&quot;) // 写反了，编译不报，线上崩溃</span></span></code></pre></div><p>Safe Args 是 Gradle 插件：</p><ol><li>在 navGraph 里给目标页面声明参数（名字、类型、是否可选）</li><li><strong>编译期自动生成 Directions、Args 类</strong></li><li>跳转时调用生成方法，参数是强类型；接收页面直接拿属性</li></ol><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// 跳转</span></span>
<span class="line"><span>findNavController().navigate(HomeFragmentDirections.actionToDetail(itemId = 100L))</span></span>
<span class="line"><span>// 接收</span></span>
<span class="line"><span>val args: DetailFragmentArgs by navArgs()</span></span>
<span class="line"><span>val id = args.itemId</span></span></code></pre></div><ul><li>类型不对、少传必填参数 → <strong>编译报错，不是线上崩溃</strong></li><li>没有魔法字符串 key，杜绝 key 拼写错误</li></ul><blockquote><p>这就是所谓<strong>类型安全</strong></p></blockquote><h3 id="navigation-整体优点" tabindex="-1">Navigation 整体优点 <a class="header-anchor" href="#navigation-整体优点" aria-label="Permalink to “Navigation 整体优点”">​</a></h3><ol><li><strong>统一路由</strong>：Fragment / Activity / Dialog 一套 API 跳转，返回栈自动管理，popUpTo、singleTop 都支持</li><li><strong>可视化导航图</strong>：Android Studio 导航编辑器，可视化看到页面流向，方便维护、新人看懂</li><li><strong>自动返回栈、返回逻辑</strong>：不用自己写 back 拦截、Fragment 回退</li><li><strong>DeepLink 原生支持</strong>：推送、外部唤醒统一走导航，参数自动解析</li><li><strong>多种 ViewModel 作用域</strong>：单页面 / 导航图流程 / Activity 三级作用域，灵活共享数据</li><li><strong>SafeArgs 类型安全传参</strong>，减少 Bundle 传参的线上 BUG</li><li>和 Jetpack 生态适配：Lifecycle、ViewModel、SavedStateHandle</li></ol><h3 id="补充一个坑点" tabindex="-1">补充一个坑点 <a class="header-anchor" href="#补充一个坑点" aria-label="Permalink to “补充一个坑点”">​</a></h3><p>navGraph scope ViewModel 依赖：<strong>这个嵌套导航图作为一个节点存在返回栈里</strong>；如果里面所有页面都 pop 出去了，这个 graph 会出栈，ViewModel 立刻清空。适合一次性流程（下单、表单），不适合全局数据。</p><h2 id="navigations-apis" tabindex="-1">Navigations APIs <a class="header-anchor" href="#navigations-apis" aria-label="Permalink to “Navigations APIs”">​</a></h2><h2 id="deeplink-深度链接" tabindex="-1">Deeplink 深度链接 <a class="header-anchor" href="#deeplink-深度链接" aria-label="Permalink to “Deeplink 深度链接”">​</a></h2><h2 id="navigation有哪些缺点" tabindex="-1">Navigation有哪些缺点？ <a class="header-anchor" href="#navigation有哪些缺点" aria-label="Permalink to “Navigation有哪些缺点？”">​</a></h2>`,32)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};